    clerkLimit: new FormControl('', { nonNullable: true }),
    floor: new FormControl('', { nonNullable: true }),
    terms: new FormControl('', { nonNullable: true }),
    latePct: new FormControl('', { nonNullable: true }),
    policyDate: new FormControl('', { nonNullable: true }),
  });
  protected readonly roleForm = new FormGroup({
    user: new FormControl('', { nonNullable: true }),
    role: new FormControl('', { nonNullable: true }),
  });
  protected readonly savingSettings = signal(false);
  protected readonly savingRole = signal(false);
  protected readonly settingsError = signal('');
  protected readonly roleError = signal('');

  constructor() {
    this.settingsForm.valueChanges.subscribe(() => this.settingsError.set(''));
    this.roleForm.valueChanges.subscribe(() => this.roleError.set(''));
    // Each load of a sheet re-reads its settings from the store and starts the forms afresh.
    effect(() => {
      const sheet = this.session.loaded();
      this.settingsError.set('');
      this.roleError.set('');
      this.show({ clerkLimit: null, floor: (DEFAULT_FLOOR_CENTS / 100).toFixed(2), terms: DEFAULT_TERMS, latePct: DEFAULT_LATE_PCT, policyDate: null, roles: [] });
      this.settingsForm.markAsPristine();
      this.settingsForm.markAsUntouched();
      if (sheet) void this.reload(sheet.id);
    });
  }

  private async reload(sheetId: string): Promise<void> {
    try {
      const settings = await this.api.get(sheetId);
      if (this.session.sheet()?.id === sheetId) this.show(settings);
    } catch {
      this.settingsError.set('The settings could not be loaded.');
    }
  }

  protected async saveSettings(): Promise<void> {
    // A second submit before the first has answered is ignored, so it stores one change, not two.
    if (this.savingSettings()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.settingsError.set('');
    const { clerkLimit, floor, terms, latePct, policyDate } = this.settingsForm.controls;
    const limit = clerkLimit.value.trim();
    const floorValue = floor.value.trim();
    const termsValue = terms.value.trim();
    const latePctValue = latePct.value.trim();
    const policyDateValue = policyDate.value.trim();
    if (changed(clerkLimit) && limit !== '' && !MONEY.test(limit)) {
      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
      return;
    }
    if (changed(floor) && !MONEY.test(floorValue)) {
      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
      return;
    }
    if (changed(terms) && (!DAYS.test(termsValue) || Number(termsValue) > 36500)) {
      this.settingsError.set('Type terms as a whole number of days, from 0 to 36500.');
      return;
    }
    if (changed(latePct) && !PCT.test(latePctValue)) {
      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
      return;
    }
    if (changed(policyDate) && policyDateValue !== '' && !isDate(policyDateValue)) {
      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
      return;
    }
    this.savingSettings.set(true);
    try {
      if (changed(clerkLimit)) {
        const settings = await this.api.setClerkLimit(sheet.id, limit === '' ? null : limit);
        settled(clerkLimit);
        if (this.session.sheet()?.id === sheet.id) this.show(settings);
      }
      if (changed(floor)) {
        const settings = await this.api.setFloor(sheet.id, floorValue);
        settled(floor);
        if (this.session.sheet()?.id === sheet.id) this.show(settings);
      }
      if (changed(terms)) {
        const settings = await this.api.setTerms(sheet.id, Number(termsValue));
        settled(terms);
        if (this.session.sheet()?.id === sheet.id) this.show(settings);
      }
      if (changed(latePct)) {
        const settings = await this.api.setLatePct(sheet.id, latePctValue);
        settled(latePct);
        if (this.session.sheet()?.id === sheet.id) this.show(settings);
      }
      if (changed(policyDate)) {
        const settings = await this.api.setPolicyDate(sheet.id, policyDateValue === '' ? null : policyDateValue);
        settled(policyDate);
        if (this.session.sheet()?.id === sheet.id) this.show(settings);
      }
    } catch {
      this.settingsError.set('The settings could not be saved.');
    } finally {
      this.savingSettings.set(false);
    }
  }

  /** Show the settings as the store answered them, and share the floor, terms, late percent and policy date with the screens showing them. */
  private show(settings: SettingsView): void {
    this.clerkLimit.set(settings.clerkLimit);
    this.floor.set(settings.floor);
    this.sheetFloor.cents.set(Math.round(Number(settings.floor) * 100));
    this.terms.set(settings.terms);
    this.sheetTerms.days.set(settings.terms);
    this.latePct.set(settings.latePct);
    this.sheetLatePct.pct.set(settings.latePct);
    this.policyDate.set(settings.policyDate);
    this.sheetPolicyDate.date.set(settings.policyDate);
    this.assigned.set(settings.roles);
  }

  protected async saveRole(): Promise<void> {
    if (this.savingRole()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.roleError.set('');
    const user = this.roleForm.getRawValue().user.trim();
    const role = this.roleForm.getRawValue().role.trim();
    if (user === '') {
      this.roleError.set('Type the user name to assign a role to.');
      return;
    }
    if (!ROLES.includes(role as Role)) {
      this.roleError.set('Choose a role of clerk or steward.');
      return;
    }
    this.savingRole.set(true);
    try {
      const saved = await this.api.setRole(sheet.id, user, role as Role);
      if (this.session.sheet()?.id === sheet.id) {
        this.assigned.update((list) =>
          [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => (a.user < b.user ? -1 : a.user > b.user ? 1 : 0)));
      }
    } catch {
      this.roleError.set('The role could not be assigned.');
    } finally {
      this.savingRole.set(false);
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** The roles a sheet can assign a user name; any name not assigned one is a clerk. */
export const ROLES = ['clerk', 'steward'] as const;
export type Role = (typeof ROLES)[number];

export interface RoleView {
  user: string;
  role: Role;
}

export interface SettingsView {
  /** The highest due a clerk may settle, with two decimals, or null when there is no limit. */
  clerkLimit: string | null;
  /** The least a claim's live due can be, with two decimals. */
  floor: string;
  /** The days after a claim's date it is due by. */
  terms: number;
  /** What an overdue claim gains of its figure for every full 30 days overdue, with two decimals. */
  latePct: string;
  /** The policy date (yyyy-mm-dd) a claim dated before rounds half up, and on or after half to even;
   *  null when blank, the sheet's today then. */
  policyDate: string | null;
  /** The roles the sheet has assigned, by user name. */
  roles: RoleView[];
}

// The sheet's settings and the roles it assigns user names, as the store holds them.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  get(sheetId: string): Promise<SettingsView> {
    return firstValueFrom(this.http.get<SettingsView>(`${this.url(sheetId)}/settings`));
  }

  /** Set the clerk limit; null clears it, leaving no limit. */
  setClerkLimit(sheetId: string, value: string | null): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheetId)}/settings/clerk-limit`, { value }));
  }

  /** Set the floor. */
  setFloor(sheetId: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheetId)}/settings/floor`, { value }));
  }

  /** Set the terms, in days. */
  setTerms(sheetId: string, value: number): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheetId)}/settings/terms`, { value }));
  }

  /** Set the late percent. */
  setLatePct(sheetId: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheetId)}/settings/late-pct`, { value }));
  }

  /** Set the policy date; null clears it, leaving the sheet's today. */
  setPolicyDate(sheetId: string, value: string | null): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheetId)}/settings/policy-date`, { value }));
  }

  /** Assign a user name a role on the sheet. */
  setRole(sheetId: string, user: string, role: Role): Promise<RoleView> {
    return firstValueFrom(this.http.put<RoleView>(`${this.url(sheetId)}/roles`, { user, role }));
  }
}

